func (t AmountValue) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"knowledge"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t AmountValue) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "known":
		return t.AsKnownAmount()
	case "unavailable":
		return t.AsMissingAmount()
	case "unknown":
		return t.AsMissingAmount()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

